function getSnippetAround(text, keyword, linesBefore = 2, linesAfter = 10) {
  const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  const results = [];
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].toLowerCase().includes(keyword.toLowerCase())) {
      const start = Math.max(0, i - linesBefore);
      const end = Math.min(lines.length, i + linesAfter + 1);
      results.push(lines.slice(start, end).join('\n'));
      i += linesAfter; // jump forward
    }
  }
  return results;
}

