const tabId = 2017691788;

const urls = [
  { name: "MacBook Air", url: "https://www.apple.com/uk/shop/buy-mac/macbook-air" },
  { name: "MacBook Pro", url: "https://www.apple.com/uk/shop/buy-mac/macbook-pro" },
  { name: "iMac", url: "https://www.apple.com/uk/shop/buy-mac/imac" },
  { name: "Mac mini", url: "https://www.apple.com/uk/shop/buy-mac/mac-mini" },
  { name: "Mac Studio", url: "https://www.apple.com/uk/shop/buy-mac/mac-studio" }
];

const results = {};

for (const item of urls) {
  await tool.navigate({ tabId, url: item.url });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });

  // Extract text and price information
  const data = await browserjs(tabId, () => {
    // Look for product cards / pricing / specs
    const text = document.body.innerText;
    const cards = Array.from(document.querySelectorAll('.rc-producttile, [data-autom="grid-item"], .rf-btr-card, [data-autom*="bundleModel"]')).map(el => el.innerText.trim());
    return {
      title: document.title,
      cards: cards.slice(0, 8),
      snippet: text.slice(0, 3000)
    };
  });

  results[item.name] = data;
}

console.log("Gathered store pages keys:", Object.keys(results));
for (const k in results) {
  console.log(`=== ${k} ===`);
  console.log("Title:", results[k].title);
  console.log("Cards count:", results[k].cards.length);
  if (results[k].cards.length > 0) {
    console.log("Cards sample:", results[k].cards.slice(0, 3));
  } else {
    console.log("Snippet:", results[k].snippet.slice(0, 500));
  }
}

