// Let's inspect the pricing and configuration tiers for each model in detail
const airText = (await read("tmp://air_specs.txt")).text;
const proText = (await read("tmp://pro_specs.txt")).text;
const imacText = (await read("tmp://imac_specs.txt")).text;
