// Let's extract the exact text of sections for each
function extractKeySections(text) {
  const sections = {};
  const lines = text.split('\n');
  let currentKey = "intro";
  sections[currentKey] = [];

  for (const line of lines) {
    const l = line.trim();
    if (["Price", "Chip", "Media Engine", "Memory", "Storage", "Display", "Charging and Expansion", "Battery and Power", "Display Support", "Audio", "Keyboard and Trackpad", "Wireless", "Camera", "Operating Requirements", "Size and Weight"].includes(l)) {
      currentKey = l;
      sections[currentKey] = [];
    } else {
      sections[currentKey].push(l);
    }
  }
  for (const k in sections) {
    sections[k] = sections[k].join('\n').trim();
  }
  return sections;
}

console.log("=== MacBook Air Sections ===");
