const tabId = 2017691788;

// Function to inspect standard configuration cards/prices on a buy page
async function inspectBuyPage(url) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });

  return await browserjs(tabId, () => {
    // Let's look for standard models / pricing buttons / bundles
    const buttons = Array.from(document.querySelectorAll('button, input[type="radio"], label')).map(el => el.innerText.trim()).filter(t => t.includes('£'));
    const priceElements = Array.from(document.querySelectorAll('[data-autom*="price"], .rc-prices-currentprice, .rf-pdp-price')).map(el => el.innerText.trim());
    const models = Array.from(document.querySelectorAll('.rc-bundle-model, [data-autom*="dimension"], .rf-btr-card')).map(el => el.innerText.trim());

    // Let's also look for all text snippets containing '£'
    const fullText = document.body.innerText;
    const priceMatches = fullText.match(/£[0-9,]+(\.[0-9]{2})?/g) || [];

    return {
      title: document.title,
      buttons: buttons.slice(0, 10),
      priceElements: priceElements.slice(0, 10),
      models: models.slice(0, 10),
      priceMatches: Array.from(new Set(priceMatches))
    };
  });
}

const buyInfo = {};
buyInfo.air = await inspectBuyPage("https://www.apple.com/uk/shop/buy-mac/macbook-air");
buyInfo.pro = await inspectBuyPage("https://www.apple.com/uk/shop/buy-mac/macbook-pro");
buyInfo.imac = await inspectBuyPage("https://www.apple.com/uk/shop/buy-mac/imac");
buyInfo.mini = await inspectBuyPage("https://www.apple.com/uk/shop/buy-mac/mac-mini");
buyInfo.studio = await inspectBuyPage("https://www.apple.com/uk/shop/buy-mac/mac-studio");

console.log("Buy Info Summary:", JSON.stringify(buyInfo, null, 2));

