const tabId = 2017691788;

const clickAll = await browserjs(tabId, () => {
  function selectRadio(name, val) {
    const input = document.querySelector(`input[name="${name}"][value="${val}"]`) || document.querySelector(`input[value="${val}"]`);
    if (input) {
      input.click();
      return true;
    }
    return false;
  }

  const results = {
    finalCut: selectRadio("software_final-preInstalledSoftware", "none"),
    logic: selectRadio("software_logic-preInstalledSoftware", "none"),
    tradeIn: selectRadio("tradeupinline", "noTradeIn")
  };

  // For AppleCare: let's find the AppleCare radio button
  const acRadio = document.querySelector('input[name="applecare-options"][value="on"]');
  if (acRadio) {
    acRadio.click();
    results.applecareOption = true;
  }

  // Then select annual or monthly plan
  const planRadio = document.querySelector('input[name="dimensionPaymentType"][value="SD2V3ZM/A-annually"]') || document.querySelector('input[value*="annually"]');
  if (planRadio) {
    planRadio.click();
    results.plan = true;
  }

  const continueBtn = document.querySelector('[data-autom="continueButton"], button[name="add-to-cart"]');
  results.continueDisabled = continueBtn ? continueBtn.disabled : "not found";

  return results;
});

console.log("Selection results:", JSON.stringify(clickAll, null, 2));

// Check continue button state after 500ms
await new Promise(r => setTimeout(r, 500));
const btnState = await browserjs(tabId, () => {
  const continueBtn = document.querySelector('[data-autom="continueButton"], button[name="add-to-cart"]');
  return {
    disabled: continueBtn ? continueBtn.disabled : null,
    text: continueBtn ? continueBtn.innerText : null
  };
});
console.log("Button state after settling:", btnState);

