  const allRadios = Array.from(document.querySelectorAll('input[type="radio"]')).map(r => ({
    name: r.name,
    value: r.value,
    checked: r.checked,
    id: r.id
  }));

  // Find which radio groups don't have any radio checked
  const groups = {};
  for (const r of allRadios) {
    if (!groups[r.name]) groups[r.name] = [];
    groups[r.name].push(r);
  }

  const uncompletedGroups = [];
  for (const name in groups) {
    if (!groups[name].some(r => r.checked)) {
      uncompletedGroups.push({
        name,
        options: groups[name].map(r => r.value)
      });
    }
  }

  const btn = document.querySelector('[data-autom="continueButton"], button[name="add-to-cart"], button[data-autom="addToCart"]');

  return {
    uncompletedGroups,
    button: {
      text: btn?.innerText,
      disabled: btn?.disabled,
      classes: btn?.className
    }
  };
});

console.log("Form status:", JSON.stringify(status, null, 2));

