const tabId = 2017691788;
await tool.navigate({ tabId, url: "https://www.apple.com/uk/shop/bag" });
await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });

const bagData = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('.rs-iteminfo-title, [data-autom="bag-item-name"], .rs-bag-item-title, h2.rs-iteminfo-title')).map(el => el.innerText.trim());
  const itemBlocks = Array.from(document.querySelectorAll('.rs-bag-item, .rs-iteminfo, tr.rs-bag-item')).map(el => ({
    title: el.querySelector('.rs-iteminfo-title, [data-autom="bag-item-name"]')?.innerText?.trim(),
    price: el.querySelector('.rs-iteminfo-price, [data-autom="bag-item-price"], .rs-summary-value')?.innerText?.trim()
  }));

  const fullText = document.body.innerText;
  const totalMatch = fullText.match(/Your bag total is £[0-9,]+(\.[0-9]{2})?/);

  return {
    url: window.location.href,
    title: document.title,
    items,
    itemBlocks: itemBlocks.filter(b => b.title),
    bagTotalString: totalMatch ? totalMatch[0] : "Not found",
    fullTextSnippet: fullText.slice(0, 3500)
  };
});

console.log("Bag URL:", bagData.url);
console.log("Total:", bagData.bagTotalString);
console.log("Items:", JSON.stringify(bagData.items, null, 2));
console.log("Item blocks:", JSON.stringify(bagData.itemBlocks, null, 2));

