const tabId = 2017691792;
const tsv = (await read("tmp://comparison_table.tsv")).text;

// Click into the spreadsheet grid area (around x=200, y=250)
await tool.mouse({
  action: "left_click",
  tabId,
  coordinate: [200, 250]
});

await new Promise(r => setTimeout(r, 500));

// Write TSV to clipboard in the page
const clipResult = await browserjs(tabId, async (tsvData) => {
  try {
    await navigator.clipboard.writeText(tsvData);
    return { ok: true };
  } catch (e) {
    return { error: e.message };
  }
}, tsv);

console.log("Clipboard write result:", clipResult);

// Now press paste
const pasteRes = await tool.press({
  tabId,
  keys: "ControlOrMeta+v"
});

console.log("Paste result:", pasteRes);
await new Promise(r => setTimeout(r, 2000));

// Take a screenshot to verify what happened
const shotAfter = await browser.screenshot({ tabId });
console.log("Screenshot after paste:", shotAfter.image.uri);

